def compute(vars):
    shares = vars["v1"]
    fair_value_per_share = vars["v2"]
    value = shares * fair_value_per_share

    return {
        "value": value,
        "trace": {
            "shares_thousands": shares,
            "weighted_average_grant_date_fair_value": fair_value_per_share,
            "value_calculation": "v1 * v2",
            "output_meta": {
                "currency": "USD",
                "scale": "thousand",
                "unit": "currency"
            }
        }
    }
